"""Parquet snapshots of the VALD ForceDecks DuckDB, written to Google Drive so Windows can read the data.

The Mac is the only writer of `data/forceplate.db` (a DuckDB file despite the .db name). The DB file itself never travels: a
live database in a synced folder gets locked and re-uploaded on every write. Instead,
after each successful pull the Mac writes one Parquet file per table to Drive, and the
Windows laptop reads those files directly (read-only).

Layout under the snapshot root (`$ATHLETE_SNAPSHOT_DIR`, else Drive):

    vald/manifest.json
    vald/<table>.parquet

The same module, with a different SOURCE and NEWEST_DATE_COLUMNS, lives in the GPS and
Perch repos. Keep them in step.

Safety rules:
- Every file is written as `<name>.tmp` and then renamed into place, so Drive never
  syncs a half-written file under the real name.
- Stale-writer guard: the tables here only grow (upserts), so a new export with FEWER
  rows than the manifest already records most likely comes from a stale copy of the
  DB (e.g. an old Windows copy). That table is refused unless `force=True`.
- Only table names and counts are ever printed; never row contents.
"""

from __future__ import annotations

import json
import os
import platform
from datetime import datetime, timezone
from pathlib import Path

SOURCE = "vald"
ENV_ROOT = "ATHLETE_SNAPSHOT_DIR"
MANIFEST = "manifest.json"

# Data date per table ("how current is this snapshot"); pull timestamps are not used.
NEWEST_DATE_COLUMNS = {
    "raw_tests": "test_date",
    "imtp_tests": "test_date",
    "classified_athletes": "test_date",
    "athlete_baselines": "baseline_date",
}

# Tables that are rebuilt rather than upserted, so a smaller row count is expected after
# a rebuild. They are still guarded; exporting a shrunk one needs --force. Listed here
# only so the refusal message can say so.
REBUILT_TABLES = {"athlete_baselines": "run_pipeline.py --reset-baseline deletes rows"}


def default_root() -> Path:
    """$ATHLETE_SNAPSHOT_DIR, else the Google Drive primary storage drive for this platform."""
    configured = os.environ.get(ENV_ROOT)
    if configured:
        return Path(configured)
    if platform.system() == "Windows":
        return Path(r"G:\My Drive\00_Primary_Storage_Drive\athlete-snapshots")
    return (Path.home() / "Library" / "CloudStorage" / "GoogleDrive-eric.rash11@gmail.com"
            / "My Drive" / "00_Primary_Storage_Drive" / "athlete-snapshots")


def source_dir(root: Path) -> Path:
    return Path(root) / SOURCE


def machine() -> str:
    return platform.node()


def _now() -> str:
    return datetime.now(timezone.utc).isoformat(timespec="seconds")


def _sql_path(path: Path) -> str:
    return Path(path).as_posix().replace("'", "''")


def _atomic_write_text(target: Path, text: str) -> None:
    tmp = target.with_name(target.name + ".tmp")
    tmp.write_text(text, encoding="utf-8")
    os.replace(tmp, target)


def list_tables(conn) -> list[str]:
    """Every base table in `main`, except transient `_`-prefixed work tables."""
    rows = conn.execute(
        "select table_name from information_schema.tables "
        "where table_schema = 'main' and table_type = 'BASE TABLE' order by 1").fetchall()
    return [r[0] for r in rows if not r[0].startswith("_")]


def read_manifest(folder: Path) -> dict:
    try:
        data = json.loads((Path(folder) / MANIFEST).read_text(encoding="utf-8"))
        return data if isinstance(data, dict) else {}
    except (OSError, ValueError):
        return {}


def previous_rows(conn, folder: Path, manifest: dict, table: str) -> int | None:
    """Row count of the snapshot already on Drive: the manifest, else the file itself."""
    entry = (manifest.get("tables") or {}).get(table)
    if isinstance(entry, dict) and isinstance(entry.get("rows"), int):
        return entry["rows"]
    existing = Path(folder) / f"{table}.parquet"
    if existing.exists():
        try:
            return conn.execute(
                f"select count(*) from read_parquet('{_sql_path(existing)}')").fetchone()[0]
        except Exception:
            return None
    return None


def newest_date(conn, table: str) -> str | None:
    column = NEWEST_DATE_COLUMNS.get(table)
    if not column:
        return None
    value = conn.execute(f'select max("{column}") from "{table}"').fetchone()[0]
    return value.isoformat() if value is not None else None


def write_table(conn, table: str, folder: Path) -> dict:
    """COPY one table to `<table>.parquet.tmp`, verify it, and rename it into place."""
    target = Path(folder) / f"{table}.parquet"
    tmp = target.with_name(target.name + ".tmp")
    conn.execute(f"copy (select * from \"{table}\") to '{_sql_path(tmp)}' "
                 "(format parquet, compression zstd)")
    rows = conn.execute(f"select count(*) from read_parquet('{_sql_path(tmp)}')").fetchone()[0]
    os.replace(tmp, target)
    return {"file": target.name, "rows": rows, "bytes": target.stat().st_size,
            "written_at": _now(), "machine": machine(),
            "newest_date_column": NEWEST_DATE_COLUMNS.get(table),
            "newest_date": newest_date(conn, table)}


def write_manifest(folder: Path, written: dict[str, dict], source_db: str) -> dict:
    """Merge this export's tables into the existing manifest (refused tables keep their row)."""
    manifest = read_manifest(folder)
    tables = dict(manifest.get("tables") or {})
    tables.update(written)
    manifest = {
        "source": SOURCE,
        "source_db": source_db,
        "exported_at": _now(),
        "machine": machine(),
        "tables": dict(sorted(tables.items())),
    }
    _atomic_write_text(Path(folder) / MANIFEST, json.dumps(manifest, indent=2) + "\n")
    return manifest


def export(conn, folder: Path, source_db: str, force: bool = False, dry_run: bool = False) -> dict:
    """Export every table to `folder`. Returns {status, tables, refused, ...}; prints counts only.

    status: "ok" (all written), "refused" (at least one table held back by the guard; the
    others were written), or "dry-run".
    """
    folder = Path(folder)
    manifest = read_manifest(folder)
    written: dict[str, dict] = {}
    refused: dict[str, dict] = {}
    for table in list_tables(conn):
        rows = conn.execute(f'select count(*) from "{table}"').fetchone()[0]
        prev = previous_rows(conn, folder, manifest, table)
        if prev is not None and prev > rows and not force:
            old = (manifest.get("tables") or {}).get(table) or {}
            refused[table] = {"rows": rows, "snapshot_rows": prev,
                              "snapshot_machine": old.get("machine"),
                              "snapshot_written_at": old.get("written_at")}
            why = REBUILT_TABLES.get(table)
            print(f"  REFUSED {table}: this DB has {rows:,} rows but the snapshot already on "
                  f"Drive has {prev:,} (written by {old.get('machine') or 'unknown'} at "
                  f"{old.get('written_at') or 'unknown'}). This DB looks stale; the snapshot "
                  "was left alone."
                  + (f" Note: {why}, so a drop can be legitimate." if why else "")
                  + " Re-run with --force only if this DB is the current one.")
            continue
        if dry_run:
            print(f"  would write {table}.parquet ({rows:,} rows"
                  + (f"; snapshot has {prev:,})" if prev is not None else ")"))
            continue
        if not written:
            folder.mkdir(parents=True, exist_ok=True)
        info = write_table(conn, table, folder)
        written[table] = info
        print(f"  {table + '.parquet':32s} {info['rows']:>10,} rows  {info['bytes'] / 1e6:7.1f} MB")

    if dry_run:
        status = "dry-run"
    else:
        if written:
            write_manifest(folder, written, source_db)
        status = "refused" if refused else "ok"
    return {"status": status, "dest": str(folder), "machine": machine(), "finished_at": _now(),
            "tables": {t: i["rows"] for t, i in written.items()}, "refused": refused}


